// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelationshipIdentityCandidate) predicate.RelationshipIdentityCandidate {
	return predicate.RelationshipIdentityCandidate(sql.AndPredicates(predicates...))
}

